<?php
require __DIR__.'/verify-demo.php';
use App\Models\IfcgSlide;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Storage;
Storage::fake('public_uploads');
Auth::logout();check(http('GET','/sales/banners')->getStatusCode()===401,'banner administration requires login');
Auth::login($admin);check(http('GET','/sales/banners')->getStatusCode()===200,'banner administration opens');
$input=['locale'=>'ar','title'=>'Media test title','description'=>'Media test description','button_text'=>'Request','button_url'=>'/request-quote','sort_order'=>2,'is_active'=>'1'];
$makeImage=fn()=>UploadedFile::fake()->createWithContent('banner.jpg',file_get_contents(public_path('ifcg/images/pages/factory-1.jpg')));
check(http('POST','/sales/banners',$input,['media'=>$makeImage()])->getStatusCode()===302,'image upload accepted');
$slide=IfcgSlide::firstOrFail();check($slide->media_type==='image' && Storage::disk('public_uploads')->exists(substr($slide->media_path,9)),'uploaded image persisted');
$r=http('GET','/?lang=ar');check(str_contains($r->getContent(),'Media test title') && str_contains($r->getContent(),$slide->media_path),'published banner appears on homepage');
check(!str_contains(http('GET','/?lang=en')->getContent(),'Media test title'),'banner respects selected language');
$input['button_url']='javascript:alert(1)';check(http('PATCH','/sales/banners/'.$slide->id,$input)->getStatusCode()===422,'unsafe banner URL rejected');
$input['button_url']='//example.test';check(http('PATCH','/sales/banners/'.$slide->id,$input)->getStatusCode()===422,'external protocol-relative URL rejected');
$input['button_url']='/shop';$input['title']='Edited media title';check(http('PATCH','/sales/banners/'.$slide->id,$input)->getStatusCode()===302 && $slide->fresh()->button_url==='/shop','banner copy and destination editable without reupload');
$video=UploadedFile::fake()->createWithContent('factory.webm',file_get_contents(public_path('ifcg/images/official-factory.webm')));
check(http('PATCH','/sales/banners/'.$slide->id,$input,['media'=>$video,'poster'=>$makeImage()])->getStatusCode()===302,'video and poster upload accepted');
check($slide->fresh()->media_type==='video' && $slide->fresh()->poster_path,'video type and poster saved');
check(str_contains(http('GET','/?lang=ar')->getContent(),'video/webm'),'homepage renders uploaded video');
$badPath=tempnam(sys_get_temp_dir(),'ifcg-check-');file_put_contents($badPath,'<?php echo 1;');
$badUpload=new UploadedFile($badPath,'bad.jpg',null,null,true);
check(http('POST','/sales/banners',$input,['media'=>$badUpload])->getStatusCode()===422,'non-media file rejected despite image extension');unlink($badPath);
check(http('DELETE','/sales/banners/'.$slide->id)->getStatusCode()===302,'banner can be hidden');
$r=http('GET','/?lang=ar');check(!str_contains($r->getContent(),'Edited media title') && str_contains($r->getContent(),'harvest-hero'),'hidden banners restore original hero');
check(str_contains($r->getContent(),'footer-columns') && str_contains($r->getContent(),'mailto:Info@ifcgegypt.com'),'footer includes navigation and working contact links');
echo "SUCCESS: $passed checks including media lifecycle.\n";
